import { useEffect, useState, useRef, useCallback } from "react";
import {
  Button,
  Grid,
  IconButton,
  MenuItem,
  Select,
  Typography,
} from "@mui/material";
import Card from "@mui/material/Card";
import Box from "@mui/material/Box";
import TextField from "@mui/material/TextField";
import PageHeader from "src/@core/components/page-header";
import Translations from "src/layouts/components/Translations";
import { axiosInstance } from "src/network/adapter";
import { ApiEndPoints } from "src/network/endpoints";
import { DefaultPaginationSettings } from "src/constants/general.const";
import { toastError, toastSuccess } from "src/utils/utils";
import DialogConfirmation from "src/views/dialog/DialogConfirmation";

import { useLocation, useNavigate, useParams } from "react-router-dom";

import DialogFeatures from "src/views/dialog/IT-Solution-Features/DialogFeatures";
import TableFeatures from "src/views/tables/IT-Solution-Features/TableFeatures";
import TableFeaturesTitle from "src/views/tables/IT-Solution-Features/TableFeaturesTitle";
import DialogFeaturesTitle from "src/views/dialog/IT-Solution-Features/DialogFeaturesTitle";

const ITSolutionFeaturesPage = () => {
  const navigate = useNavigate();
  const searchTimeoutRef = useRef();
  const [loading, setLoading] = useState(false);
  const [featuresData, setFeaturesData] = useState([]);
  const [featureTitle, setFeatureTitle] = useState([]);
  const [search, setSearch] = useState("");
  const [totalCount, setTotalCount] = useState(0);
  const [currentPage, setCurrentPage] = useState(1);
  const [pageSize, setPageSize] = useState(
    DefaultPaginationSettings.ROWS_PER_PAGE
  );
  const [status, setStatus] = useState("");
  // Testimonials
  const [featuresFormDialogOpen, setFeaturesFormDialogOpen] = useState(false);
  const [featuresFormDialogMode, setFeaturesFormDialogMode] = useState("add");
  const [featuresToEdit, setFeaturesToEdit] = useState(null);

  const [featureTitleDialogOpen, setFeatureTitleDialogOpen] = useState(false);
  const [featureTitleDialogMode, setFeatureTitleDialogMode] = useState("add");
  const [featureTitleToEdit, setFeatureTitleToEdit] = useState(null);
  const [diableAddTitle, setDiableAddTitle] = useState(false);

  // Confirmation
  const [confirmationDialogLoading, setConfirmationDialogLoading] =
    useState(false);
  const [confirmationDialogOpen, setConfirmationDialogOpen] = useState(false);
  const [featuresToDelete, setFeaturesToDelete] = useState(null);
  const { id } = useParams();
  const [disableDeleteButton, setDisableDeleteButton] = useState(false);
  const [deleteType, setDeleteType] = useState("");

  const toggleFeaturesFormDialog = (e, mode = "add", featuresToEdit = null) => {
    setFeaturesFormDialogOpen((prev) => !prev);
    setFeaturesFormDialogMode(mode);
    setFeaturesToEdit(featuresToEdit);
  };

  const toggleFeatureTitleFormDialog = (
    e,
    mode = "add",
    featureTitleToEdit = null
  ) => {
    setFeatureTitleDialogOpen((prev) => !prev);
    setFeatureTitleDialogMode(mode);
    setFeatureTitleToEdit(featureTitleToEdit);
  };
  const toggleConfirmationDialog = (e, deletetype, dataToDelete = null) => {
    setConfirmationDialogOpen((prev) => !prev);
    setFeaturesToDelete(dataToDelete);
    setDeleteType(deletetype);
  };

  const fetchData = ({
    currentPage,
    pageSize = DefaultPaginationSettings.ROWS_PER_PAGE,
    search,
    status,
  }) => {
    setLoading(true);
    let params = {
      page: currentPage,
      limit: pageSize,
      search: search,
      status: status,
    };

    axiosInstance
      .get(ApiEndPoints.ITSolutionFeatures.list(id), { params })
      .then((response) => {
        const responseData = response.data.data;
        setFeaturesData(response.data.data);
        setTotalCount(response.data.data.totalCount);
        if (responseData.length === 1) {
          setDisableDeleteButton(true);
        } else {
          setDisableDeleteButton(false); // Enable the button if there is no data
        }
      })
      .catch((error) => {
        toastError(error);
      })
      .finally(() => {
        setLoading(false);
      });
  };
  const fetchTitle = () => {
    setLoading(true);
    axiosInstance
      .get(ApiEndPoints.ITSolutionFeatureTitle.list(id))
      .then((response) => {
        const responseData = response.data.data;

        if (responseData.length > 0) {
          setDiableAddTitle(true);
        } else {
          setDiableAddTitle(false); // Enable the button if there is no data
        }
        setFeatureTitle(response.data.data);
        setTotalCount(response.data.data.totalCount);
      })
      .catch((error) => {
        toastError(error);
      })
      .finally(() => {
        setLoading(false);
      });
  };
  useEffect(() => {
    fetchData({
      currentPage: currentPage,
      pageSize: pageSize,
      search: search,
      status: status,
    });
    fetchTitle();
  }, [currentPage, pageSize, search, status]);

  const onConfirmDelete = useCallback(
    (e) => {
      e?.preventDefault();
      setConfirmationDialogLoading(true);
      const deleteUrl =
        deleteType === "deleteFeature"
          ? ApiEndPoints.ITSolutionFeatures.delete(featuresToDelete.id)
          : ApiEndPoints.ITSolutionFeatureTitle.delete(featuresToDelete.id);
      axiosInstance
        .delete(deleteUrl)
        .then((response) => response.data)
        .then((response) => {
          deleteType === "deleteFeature"
            ? fetchData({
                currentPage: currentPage,
                pageSize: pageSize,
                search: search,
              })
            : fetchTitle({
                currentPage: currentPage,
                pageSize: pageSize,
                search: search,
              });

          toggleConfirmationDialog();
          toastSuccess(response.message);
        })
        .catch((error) => {
          toastError(error);
        })
        .finally(() => {
          setConfirmationDialogLoading(false);
        });
    },
    [currentPage, featuresToDelete, pageSize, search]
  );
  const handleCellClick = (rowData) => {
    navigate(`/it-solution-sub-features/${rowData.row.id}`, {
      state: rowData.row,
    });
  };

  return (
    <>
      <Grid container rowGap={10}>
        <Grid container spacing={4} className="match-height">
          <PageHeader
            title={
              <Typography variant="h5">
                <Translations text="Feature's Title " />
              </Typography>
            }
            action={
              <Button
                variant="contained"
                disabled={diableAddTitle}
                onClick={toggleFeatureTitleFormDialog}
              >
                Add Title
              </Button>
            }
          />
          <Grid item xs={12}>
            <Card>
              <Box sx={{ p: 5 }}>
                <TableFeaturesTitle
                  search={search}
                  loading={loading}
                  rows={featureTitle}
                  totalCount={totalCount}
                  setCurrentPage={setCurrentPage}
                  currentPage={currentPage}
                  setPageSize={setPageSize}
                  pageSize={pageSize}
                  toggleDelete={toggleConfirmationDialog}
                  toggleEdit={toggleFeatureTitleFormDialog}
                />
              </Box>
            </Card>
          </Grid>
        </Grid>
        <Grid container spacing={4} className="match-height">
          <PageHeader
            title={
              <Typography variant="h5">
                <Translations text="Features" />
              </Typography>
            }
            action={
              <Button variant="contained" onClick={toggleFeaturesFormDialog}>
                Add Features
              </Button>
            }
          />
          <Grid item xs={12}>
            <Card>
              <Box sx={{ p: 5 }}>
                <TableFeatures
                  search={search}
                  loading={loading}
                  rows={featuresData}
                  totalCount={totalCount}
                  setCurrentPage={setCurrentPage}
                  currentPage={currentPage}
                  setPageSize={setPageSize}
                  pageSize={pageSize}
                  toggleDelete={toggleConfirmationDialog}
                  toggleEdit={toggleFeaturesFormDialog}
                  onCellClick={(rowData) => handleCellClick(rowData)}
                  disableDeleteButton={disableDeleteButton}
                />
              </Box>
            </Card>
          </Grid>
        </Grid>
      </Grid>

      <DialogFeaturesTitle
        mode={featureTitleDialogMode}
        open={featureTitleDialogOpen}
        toggle={toggleFeatureTitleFormDialog}
        dataToEdit={featureTitleToEdit}
        itSolutionId={id}
        onSuccess={() => {
          fetchTitle();
        }}
      />
      <DialogFeatures
        mode={featuresFormDialogMode}
        open={featuresFormDialogOpen}
        toggle={toggleFeaturesFormDialog}
        itSolutionId={id}
        dataToEdit={featuresToEdit}
        onSuccess={() => {
          fetchData({
            currentPage: currentPage,
            pageSize: pageSize,
          });
        }}
      />
      <DialogConfirmation
        loading={confirmationDialogLoading}
        title={
          deleteType === "deleteFeature"
            ? "Delete Feature"
            : "Delete Feature Title"
        }
        subtitle={
          deleteType === "deleteFeature"
            ? "Are you sure you want to delete this Feature?"
            : "Are you sure you want to delete this Feature Title?"
        }
        open={confirmationDialogOpen}
        toggle={toggleConfirmationDialog}
        onConfirm={onConfirmDelete}
      />
    </>
  );
};

export default ITSolutionFeaturesPage;
